const raw = $input.first().json;

// Parser le body correctement — supporte string avec = parasite
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

if (!data.task_id) {
  return [{
    json: {
      valid: "NO",
      error_code: "VALIDATION_ERROR",
      error_message: "task_id manquant",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!data.environment) {
  return [{
    json: {
      valid: "NO",
      error_code: "VALIDATION_ERROR",
      error_message: "environment manquant",
      timestamp: new Date().toISOString()
    }
  }];
}

if (!data.gonogo_decision) {
  return [{
    json: {
      valid: "NO",
      error_code: "VALIDATION_ERROR",
      error_message: "gonogo_decision manquant",
      timestamp: new Date().toISOString()
    }
  }];
}

if (data.gonogo_decision !== 'CONTINUE') {
  return [{
    json: {
      valid: "NO",
      error_code: "BLOCKED",
      error_message: `Déploiement bloqué — décision Go/No-Go : ${data.gonogo_decision}`,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    valid: "YES",
    task_id: data.task_id,
    project_context: data.project_context || '',
    environment: data.environment,
    language: data.code?.language || 'javascript',
    framework: data.code?.framework || 'express',
    files: data.code?.files || [],
    gonogo_decision: data.gonogo_decision
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent DevOps/Deploy",
    task_id: input.task_id || "unknown",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp || new Date().toISOString()
  }
}];

const input = $input.first().json;
const environment = input.environment || 'staging';
const language = input.language || 'javascript';
const framework = (input.framework || 'express').toLowerCase();

// ── CONFIGS ──────────────────────────────────────────────────
const configs = {
  express: {
    staging: {
      platform: 'contabo',
      build_command: 'npm install',
      start_command: 'node server.js',
      env_vars: ['NODE_ENV=staging', 'PORT=3000'],
      health_check: '/health'
    },
    production: {
      platform: 'contabo',
      build_command: 'npm install --production',
      start_command: 'node server.js',
      env_vars: ['NODE_ENV=production', 'PORT=3000'],
      health_check: '/health'
    }
  },
  fastapi: {
    staging: {
      platform: 'contabo',
      build_command: 'pip install -r requirements.txt',
      start_command: 'uvicorn main:app --host 0.0.0.0 --port 8000',
      env_vars: ['ENV=staging'],
      health_check: '/health'
    },
    production: {
      platform: 'contabo',
      build_command: 'pip install -r requirements.txt',
      start_command: 'uvicorn main:app --host 0.0.0.0 --port 8000',
      env_vars: ['ENV=production'],
      health_check: '/health'
    }
  }
};

const config = configs[framework]?.[environment] || configs.express.staging;

// ── PIPELINE CI/CD ────────────────────────────────────────────
const pipelines = {
  express: `name: CI/CD Pipeline\non:\n  push:\n    branches: [main]\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v3\n      - uses: actions/setup-node@v3\n        with:\n          node-version: '18'\n      - run: npm install\n      - run: npm test\n      - name: Deploy to ${environment}\n        run: echo "Deploy to ${environment}"`,
  fastapi: `name: CI/CD Pipeline\non:\n  push:\n    branches: [main]\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v3\n      - uses: actions/setup-python@v4\n        with:\n          python-version: '3.11'\n      - run: pip install -r requirements.txt\n      - run: pytest\n      - name: Deploy to ${environment}\n        run: echo "Deploy to ${environment}"`
};

const pipeline_content = pipelines[framework] || pipelines.express;

// ── STATUT DÉPLOIEMENT ────────────────────────────────────────
const deploy_status = environment === 'production'
  ? 'PENDING_APPROVAL'
  : 'SUCCESS';

const warnings = environment === 'production'
  ? ['Déploiement production nécessite approbation manuelle']
  : [];

return [{
  json: {
    task_id: input.task_id,
    agent: "Agent DevOps/Deploy",
    deploy_status,
    environment,
    language,
    framework,
    config,
    pipeline: {
      file: '.github/workflows/deploy.yml',
      content: pipeline_content
    },
    warnings,
    next_agent: deploy_status === 'SUCCESS' ? 'Agent Monitoring' : 'MANUAL_APPROVAL',
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
const isSuccess = input.deploy_status === 'SUCCESS';
const isPending = input.deploy_status === 'PENDING_APPROVAL';

let status;
if (isSuccess) status = "PASS";
else if (isPending) status = "NEEDSIMPROVEMENT";
else status = "FAIL";

return [{
  json: {
    success: isSuccess,
    agent: "Agent DevOps/Deploy",
    task_id: input.task_id || "unknown",
    status,
    global_score: isSuccess ? 100 : isPending ? 75 : 0,
    approved_for_pipeline: isSuccess,
    language: input.language || "javascript",
    critical_issues: status === "FAIL"
      ? [{ severity: "high", description: "Déploiement échoué" }]
      : [],
    warnings: input.warnings || [],
    recommendations: isSuccess
      ? ["Déploiement staging réussi — pipeline CI/CD généré"]
      : isPending
        ? ["Déploiement production en attente d'approbation manuelle"]
        : ["Corriger les erreurs de déploiement"],
    summary: isSuccess
      ? `Déploiement ${input.environment} réussi`
      : `Déploiement ${input.environment} — ${input.deploy_status}`,
    dimensions: {
      security: { score: 100 },
      quality: { score: isSuccess ? 100 : 75 }
    },
    timestamp: input.timestamp || new Date().toISOString(),
    deployment: input.config || {},
    pipeline_file: input.pipeline?.file || '',
    next_agent: input.next_agent || ''
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent DevOps/Deploy",
    task_id: input.task_id,
    status: "FAIL",
    global_score: 0,
    approved_for_pipeline: false,
    language: input.language,
    critical_issues: [{ severity: "high", description: "Déploiement échoué" }],
    warnings: [],
    recommendations: ["Corriger les erreurs de déploiement"],
    summary: "Échec du déploiement",
    dimensions: { security: { score: 0 }, quality: { score: 0 } },
    timestamp: input.timestamp || new Date().toISOString()
  }
}];
